css:
.commsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e9ecf5;
    background:
        radial-gradient(circle at 85% -10%, rgba(124, 92, 255, 0.18) 0%, rgba(124, 92, 255, 0) 45%),
        linear-gradient(155deg, #1b1d3a 0%, #14162b 55%, #0e0f1d 100%);
    border-radius: 18px;
}

.commsim-container * {
    box-sizing: border-box;
}

.commsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(120deg, #221a4a 0%, #2c2566 50%, #173a5e 100%);
    color: #f3f0ff;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #38336b;
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.5);
    position: relative;
    overflow: hidden;
}

.commsim-header::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(124, 222, 255, 0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(124, 222, 255, 0.05) 1px, transparent 1px);
    background-size: 26px 26px;
    pointer-events: none;
}

.commsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
    position: relative;
}

.commsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #7cf0d8;
    background: rgba(124, 240, 216, 0.12);
    border: 1px solid rgba(124, 240, 216, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
    position: relative;
}

.commsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c9c8ee;
    position: relative;
}

.commsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #a7a6cf;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.commsim-period-counter #currentDay,
.commsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #7cf0d8;
}

.commsim-round-name {
    background: rgba(124, 240, 216, 0.14);
    color: #7cf0d8;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.commsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffce6b;
    background: rgba(255, 206, 107, 0.12);
    border: 1px solid rgba(255, 206, 107, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.commsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.commsim-status-card {
    background: linear-gradient(160deg, #232548 0%, #1a1c36 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #322f5e;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.38);
    border-top: 4px solid #5b54a8;
}

.commsim-card-runway { border-top-color: #ffce6b; }
.commsim-card-validated { border-top-color: #7cf0d8; }
.commsim-card-novelty { border-top-color: #7c9cff; }
.commsim-card-risk { border-top-color: #ff7a8a; }

.commsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #9694c2;
}

.commsim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.commsim-card-runway .commsim-value { color: #ffce6b; }
.commsim-card-validated .commsim-value { color: #7cf0d8; }
.commsim-card-novelty .commsim-value { color: #7c9cff; }
.commsim-card-risk .commsim-value { color: #ff7a8a; }

.commsim-sublabel {
    font-size: 0.76rem;
    color: #8d8cb6;
    line-height: 1.35;
}

.commsim-runway-critical { border-top-color: #ff4d6d; }
.commsim-runway-critical .commsim-value { color: #ff5c74; }
.commsim-runway-healthy .commsim-value { color: #ffe08a; }

.commsim-risk-high { border-top-color: #ff4d6d; }
.commsim-risk-high .commsim-value { color: #ff5c74; }
.commsim-risk-low { border-top-color: #7cf0d8; }
.commsim-risk-low .commsim-value { color: #7cf0d8; }

.commsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16182f;
    border: 1px solid #322f5e;
    color: #d9d8f1;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.commsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #7cf0d8;
}

.commsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #232548 0%, #1a1c36 100%);
    border-left: 5px solid #7cf0d8;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.32);
}

.commsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.commsim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.commsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c8c7ea;
}

.commsim-briefing-text strong { color: #7cf0d8; }
.commsim-briefing-text em { color: #ffce6b; font-style: italic; }

.commsim-controls {
    background: linear-gradient(160deg, #1d1f3c 0%, #16182f 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #322f5e;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.32);
}

.commsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid #322f5e;
    padding-bottom: 8px;
}

.commsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d3d2ef;
    margin: 14px 0 6px;
}

.commsim-container select,
.commsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #3a3768;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #181a33;
    color: #edecfb;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.commsim-container select:focus,
.commsim-container input[type="number"]:focus {
    outline: none;
    border-color: #7cf0d8;
    box-shadow: 0 0 0 3px rgba(124, 240, 216, 0.2);
}

.commsim-container select option {
    background-color: #181a33;
    color: #edecfb;
}

.commsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #7cf0d8;
}

.commsim-range-readout,
.commsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #a7a6cf;
    margin-top: 4px;
}

.commsim-range-readout span:nth-child(2),
.commsim-alloc-readout #allocReadout {
    color: #7cf0d8;
    font-weight: 800;
}

.commsim-hint {
    font-size: 0.8rem;
    color: #8d8cb6;
    margin-top: 4px;
    line-height: 1.4;
}

.commsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.commsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #181a33;
    border: 1px solid #322f5e;
    border-radius: 9px;
    padding: 8px 12px;
}

.commsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #d3d2ef;
}

.commsim-alloc-row input[type="number"] {
    width: 84px;
    flex: 0 0 84px;
}

.commsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.commsim-container .btn-primary {
    background: linear-gradient(135deg, #2d8f7e 0%, #7cf0d8 100%);
    border: none;
    color: #06241e;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(45, 143, 126, 0.42);
}

.commsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.commsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #3a3768;
    color: #a7a6cf;
    background: transparent;
}

.commsim-coach {
    background: linear-gradient(160deg, #1a1530 0%, #1d2540 100%);
    color: #ddd9f4;
    border: 1px solid #3a3768;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.32);
}

.commsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffce6b;
    margin-bottom: 8px;
}

.commsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.commsim-coach-body strong { color: #7cf0d8; }
.commsim-coach-body em { color: #ffce6b; font-style: italic; }

.commsim-history,
.commsim-chart {
    background: linear-gradient(160deg, #1d1f3c 0%, #16182f 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #322f5e;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.32);
}

.commsim-history h3,
.commsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.commsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #d3d2ef;
}

.commsim-container table#usfHistoryTable th {
    background: #181a33;
    color: #7cf0d8;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #322f5e;
}

.commsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #2a2850;
    color: #c8c7ea;
}

.commsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #191b36;
}

.commsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .commsim-container {
        padding: 14px;
    }
    .commsim-header h1 {
        font-size: 1.7rem;
    }
    .commsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .commsim-value {
        font-size: 2.1rem;
    }
    .commsim-clock {
        margin-left: 0;
    }
    .commsim-period-counter {
        font-size: 0.88rem;
    }
    .commsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .commsim-alloc-row {
        flex-wrap: wrap;
    }
    .commsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .commsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.commsim-cm { background:#f5f4fb; color:#1c1b2b; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.commsim-cm-head { text-align:center; border-bottom:1px solid #e0def0; padding-bottom:14px; margin-bottom:16px; }
.commsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#5c5a78; font-weight:700; }
.commsim-cm-scorewrap { margin:8px 0 2px; }
.commsim-cm-score { font-size:52px; font-weight:800; color:#5b53b8; line-height:1; }
.commsim-cm-score-max { font-size:20px; color:#9088ab; font-weight:600; }
.commsim-cm-grade { font-size:19px; font-weight:700; color:#1c1b2b; margin-top:4px; }
.commsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.commsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.commsim-cm-met { background:#d5e8dd; color:#1c6b4e; }
.commsim-cm-fail { background:#f2dddc; color:#a2382f; }
.commsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.commsim-cm-metric { background:#eae8f6; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.commsim-cm-metric-val { font-size:22px; font-weight:800; color:#1c1b2b; }
.commsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#5c5a78; margin-top:3px; }
.commsim-cm-insights { background:#eae8f6; border-radius:10px; padding:14px 18px; }
.commsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#5c5a78; font-weight:700; margin-bottom:8px; }
.commsim-cm-insights ul { margin:0; padding-left:18px; }
.commsim-cm-insights li { font-size:14px; line-height:1.5; color:#2e2c3f; margin-bottom:7px; }

