(function() {
    'use strict';

    class CommercializeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Commercialize It`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Tessellate Labs Inc.).
            this.CASH = 420;                 // C$420k in the bank
            this.BURN = 30;                  // C$30k / month
            this.START_RUNWAY = 14;          // ~14 months
            this.WEEK_BURN = 7;              // ~C$7k of runway per week of building
            this.BUILD_COST_MONTHS = 4;      // premature MVP build = 4 months of runway
            this.VALIDATION_BUDGET = 25;     // C$25k fixed validation sprint
            this.TRANCHE = 90;               // C$90k grant tranche at stake
            this.TOTAL_ASSUMPTIONS = 20;     // ~20 critical assumptions
            this.START_VALIDATED = 3;        // 3 tested at start

            // Experiment costs (C$k) and base signal strength (validated-assumption yield).
            this.EXP = {
                interviews: { cost: 3, signal: 2.0 },   // medium signal, surfaces the real buyer
                smoke:      { cost: 6, signal: 1.6 },    // demand signal
                pilot:      { cost: 12, signal: 4.0 },   // strongest willingness-to-pay signal
                concierge:  { cost: 10, signal: 3.2 },   // high signal, non-scalable
                field:      { cost: 9, signal: 2.6 }     // technical-feasibility signal
            };

            // Concept truths.
            this.TRUE_ROUTE = `direct`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    runway: this.START_RUNWAY,   // months of cash left
                    validated: this.START_VALIDATED, // assumptions tested with real buyers
                    novelty: 2.0,                // idea-novelty score (1-5)
                    risk: 60,                    // unpriced commercialization risk (0-100, lower better)
                    budgetUsed: 0,               // C$k of validation budget committed (R3)
                    builtFirst: false,
                    aiOracle: false,
                    sprayed: false,
                    wrongBuyer: false,
                    optionalityAddicted: false,
                    runwayHistory: [this.START_RUNWAY],
                    validatedHistory: [this.START_VALIDATED],
                    noveltyHistory: [2.0],
                    riskHistory: [60],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately middling / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    problem: `product`,
                    leap: `build`,
                    focus: 3,
                    mode: `divergent`,
                    human: `nothing`,
                    novelty: 2,
                    interviews: 6,
                    smoke: 6,
                    pilot: 0,
                    concierge: 0,
                    field: 13,
                    spread: `spread`,
                    signal: `ignore`,
                    route: `direct`,
                    ttm: 6,
                    milestone: `mvp`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pr = document.getElementById(`problemInput`);
                const lp = document.getElementById(`leapInput`);
                const fc = document.getElementById(`focusInput`);
                if (pr) decisions.problem = pr.value;
                if (lp) decisions.leap = lp.value;
                if (fc) decisions.focus = parseInt(fc.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 1 || decisions.focus > 4) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const md = document.getElementById(`modeInput`);
                const hm = document.getElementById(`humanInput`);
                const nv = document.getElementById(`noveltyInput`);
                if (md) decisions.mode = md.value;
                if (hm) decisions.human = hm.value;
                if (nv) decisions.novelty = parseInt(nv.value, 10);
                if (!Number.isFinite(decisions.novelty) || decisions.novelty < 1 || decisions.novelty > 5) {
                    warn(`warn_novelty_range`); return false;
                }
            } else if (round === 3) {
                const iv = document.getElementById(`interviewsInput`);
                const sm = document.getElementById(`smokeInput`);
                const pl = document.getElementById(`pilotInput`);
                const cg = document.getElementById(`conciergeInput`);
                const fd = document.getElementById(`fieldInput`);
                const sp = document.getElementById(`spreadInput`);
                const sg = document.getElementById(`signalInput`);
                if (iv) decisions.interviews = parseFloat(iv.value);
                if (sm) decisions.smoke = parseFloat(sm.value);
                if (pl) decisions.pilot = parseFloat(pl.value);
                if (cg) decisions.concierge = parseFloat(cg.value);
                if (fd) decisions.field = parseFloat(fd.value);
                if (sp) decisions.spread = sp.value;
                if (sg) decisions.signal = sg.value;
                const parts = [decisions.interviews, decisions.smoke, decisions.pilot, decisions.concierge, decisions.field];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = decisions.interviews + decisions.smoke + decisions.pilot + decisions.concierge + decisions.field;
                if (Math.abs(total - this.VALIDATION_BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const rt = document.getElementById(`routeInput`);
                const tm = document.getElementById(`ttmInput`);
                const ms = document.getElementById(`milestoneInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rt) decisions.route = rt.value;
                if (tm) decisions.ttm = parseInt(tm.value, 10);
                if (ms) decisions.milestone = ms.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.ttm) || decisions.ttm < 2 || decisions.ttm > 20) {
                    warn(`warn_ttm_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let runwayDelta = 0, validatedDelta = 0, noveltyDelta = 0, riskDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Frame the problem in customer language, not product language.
                switch (d.problem) {
                    case `customer`: riskDelta -= 8; noveltyDelta += 0.3; coachKey = `coach_r1_customer`; break;
                    case `feature`: riskDelta += 4; coachKey = `coach_r1_feature`; break;
                    case `product`: riskDelta += 6; coachKey = `coach_r1_product`; break;
                }

                // Build-first vs audit-first (Common Error 1: build-first burns the scarcest resource).
                switch (d.leap) {
                    case `audit`:
                        riskDelta -= 12; validatedDelta += 1;
                        if (d.problem === `customer`) coachKey = `coach_r1_sharp`;
                        break;
                    case `parallel`:
                        // A "smaller" build still burns ~2 months against untested demand.
                        runwayDelta -= 2; riskDelta += 6; ds.builtFirst = true; coachKey = `coach_r1_parallel`;
                        break;
                    case `build`:
                        // The classic trap: C$120k = 4 months of runway, 13 of 20 assumptions still untested.
                        runwayDelta -= this.BUILD_COST_MONTHS; riskDelta += 16; ds.builtFirst = true; coachKey = `coach_r1_build`;
                        break;
                }

                // Focus: every extra market dilutes runway 4-to-1 and raises risk.
                const extraMarkets = d.focus - 1;       // 0 = one beachhead, 3 = all four
                riskDelta += extraMarkets * 5;
                runwayDelta -= extraMarkets * 0.5;       // diffuse effort quietly burns runway
                if (d.focus === 1) { riskDelta -= 6; }
                else if (d.focus === 4) { coachKey = `coach_r1_fourmarkets`; }

                summaryKey = (d.leap === `audit` && d.problem === `customer` && d.focus <= 2) ? `sum_r1_good` :
                             (d.leap === `build` ? `sum_r1_build` : `sum_r1_weak`);
            } else if (round === 2) {
                // AI-augmented ideation (Common Error 2: AI-as-oracle; Maxwell's thesis).
                // Each mode has a different failure trap; the human-judgment lever decides which way it breaks.
                const humanOwns = d.human === `judgment`;
                const targetNovelty = d.novelty;         // the bar the team commits to

                // Realised novelty: a high bar only sticks if a human owns the filter.
                let realisedNovelty;
                if (d.mode === `oracle`) {
                    // Take the AI's answer: high volume, low novelty, indistinguishable from rivals.
                    realisedNovelty = 2.0; ds.aiOracle = true; riskDelta += 8; coachKey = `coach_r2_oracle`;
                } else if (humanOwns) {
                    // Structure + human-owned judgment supercharges each step.
                    realisedNovelty = Math.min(5, targetNovelty + 0.5);
                    riskDelta -= 6;
                    switch (d.mode) {
                        case `divergent`: coachKey = `coach_r2_divergent`; break;
                        case `convergent`: coachKey = `coach_r2_convergent`; break;
                        case `synthetic`: coachKey = `coach_r2_synthetic`; validatedDelta += 0.5; break;
                    }
                } else {
                    // A structured mode but no human owning novelty: the bar is aspirational only.
                    realisedNovelty = Math.min(targetNovelty, 2.5);
                    riskDelta += 3; coachKey = `coach_r2_nohuman`;
                }

                // Move novelty toward the realised level (don't just add a target you didn't earn).
                noveltyDelta += (realisedNovelty - ds.novelty);

                // The synthetic-customer trap: false confidence if the human doesn't keep judgment.
                if (d.mode === `synthetic` && !humanOwns) { riskDelta += 4; coachKey = `coach_r2_synthtrap`; }
                // Divergent trap: inflated volume drowns the signal without a human filter.
                if (d.mode === `divergent` && !humanOwns && d.human === `polish`) { coachKey = `coach_r2_volume`; }

                summaryKey = (humanOwns && d.mode !== `oracle` && d.novelty >= 4) ? `sum_r2_good` :
                             (d.mode === `oracle` || (!humanOwns)) ? `sum_r2_oracle` : `sum_r2_weak`;
            } else if (round === 3) {
                // Cheap validation sprint (Common Error 3: validation spray; Error 4: wrong buyer).
                const iv = d.interviews, sm = d.smoke, pl = d.pilot, cg = d.concierge, fd = d.field;

                // Validated-assumption yield = budget in each line × its signal-per-dollar.
                let yieldRaw =
                    (iv / this.EXP.interviews.cost) * this.EXP.interviews.signal +
                    (sm / this.EXP.smoke.cost) * this.EXP.smoke.signal +
                    (pl / this.EXP.pilot.cost) * this.EXP.pilot.signal +
                    (cg / this.EXP.concierge.cost) * this.EXP.concierge.signal +
                    (fd / this.EXP.field.cost) * this.EXP.field.signal;

                // Concentration multiplier: the same C$25k buys hard evidence on one bet,
                // weak signal on four (Common Error 3).
                let concFactor = 1.0;
                switch (d.spread) {
                    case `concentrate`: concFactor = 1.25; riskDelta -= 8; break;
                    case `two`: concFactor = 1.0; riskDelta -= 2; break;
                    case `spread`: concFactor = 0.55; riskDelta += 8; coachKey = `coach_r3_spray`; ds.sprayed = true; break;
                }

                validatedDelta += yieldRaw * concFactor;

                // The validation sprint costs runway too: 4 simulated weeks of work.
                runwayDelta -= 1;
                spend = iv + sm + pl + cg + fd;

                // Signal card: the real buyer is the quality manager, not the plant owner.
                switch (d.signal) {
                    case `pivot`:
                        validatedDelta += 2; riskDelta -= 12;
                        if (d.spread !== `spread`) coachKey = `coach_r3_pivot`;
                        break;
                    case `note`:
                        riskDelta += 4; coachKey = `coach_r3_note`;
                        break;
                    case `ignore`:
                        riskDelta += 12; ds.wrongBuyer = true; coachKey = `coach_r3_wrongbuyer`;
                        break;
                }

                // Interviews are what surface the buyer at all — ignoring them blinds the team.
                if (iv <= 0 && d.signal === `pivot`) { validatedDelta -= 1.5; coachKey = `coach_r3_nointerviews`; }

                if (coachKey === `coach_default`) {
                    coachKey = (concFactor >= 1.25) ? `coach_r3_concentrate` : `coach_r3_mixed`;
                }

                summaryKey = (d.spread !== `spread` && d.signal === `pivot` && pl > 0) ? `sum_r3_good` :
                             (d.spread === `spread` ? `sum_r3_spray` : `sum_r3_weak`);
            } else if (round === 4) {
                // Commit to one route & defend the runway (Common Error 5: optionality addiction).
                switch (d.route) {
                    case `direct`:
                        // Slow, high-margin, defensible — the concept's recommended beachhead.
                        riskDelta -= 14; coachKey = `coach_r4_direct`; break;
                    case `oem`:
                        // Fast reach but margin & control surrendered.
                        riskDelta -= 4; runwayDelta += 0.5; coachKey = `coach_r4_oem`; break;
                    case `api`:
                        // Scalable but unvalidated demand & longest time-to-revenue.
                        riskDelta += 6; runwayDelta -= 0.5; coachKey = `coach_r4_api`; break;
                    case `all`:
                        // Refused to kill any route — recreates the diffusion that triggered the ultimatum.
                        riskDelta += 18; runwayDelta -= 1; ds.optionalityAddicted = true; coachKey = `coach_r4_all`; break;
                }

                // An API bet with no validated demand is the co-founder's pet route the data didn't support.
                if (d.route === `api` && ds.validated < 10) { riskDelta += 6; }

                // Time-to-MVP: too aggressive isn't real; too long burns selling time.
                const ttmRunwayCost = (d.ttm * this.WEEK_BURN) / this.BURN; // weeks → months of runway
                runwayDelta -= ttmRunwayCost;
                if (d.ttm <= 3) { riskDelta += 6; coachKey = `coach_r4_tooaggressive`; }       // not a real MVP
                else if (d.ttm >= 16) { riskDelta += 8; coachKey = `coach_r4_toolong`; }        // no selling time
                else { riskDelta -= 3; }                                                        // a defensible window

                // Funding-unlock milestone (Common Error: aggressive TTM with no milestone link).
                switch (d.milestone) {
                    case `paying`: riskDelta -= 12; if (d.route === `direct`) coachKey = `coach_r4_milestone`; break;
                    case `vanity`: riskDelta += 8; coachKey = `coach_r4_vanity`; break;
                    case `mvp`: riskDelta += 6; coachKey = `coach_r4_mvpmilestone`; break;
                }

                if (d.conviction >= 60) { riskDelta -= 5; }
                else if (d.conviction <= 25) { riskDelta += 5; }

                summaryKey = (d.route !== `all` && d.milestone === `paying` && d.ttm > 3 && d.ttm < 16) ? `sum_r4_good` :
                             (d.route === `all` ? `sum_r4_all` : `sum_r4_weak`);
            }

            // Resource accounting: only the C$25k validation budget is metered here (R3).
            ds.budgetUsed = Math.min(this.VALIDATION_BUDGET, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply deltas with clamps. Runway can go negative (out of cash); the rest are bounded.
            ds.runway = Math.round((ds.runway + runwayDelta) * 10) / 10;
            ds.validated = Math.max(0, Math.min(this.TOTAL_ASSUMPTIONS, Math.round((ds.validated + validatedDelta) * 10) / 10));
            ds.novelty = Math.max(1, Math.min(5, Math.round((ds.novelty + noveltyDelta) * 10) / 10));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            ds.runwayHistory.push(ds.runway);
            ds.validatedHistory.push(ds.validated);
            ds.noveltyHistory.push(ds.novelty);
            ds.riskHistory.push(ds.risk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                runway: ds.runway,
                runwayDelta: Math.round(runwayDelta * 10) / 10,
                validated: ds.validated,
                validatedDelta: Math.round(validatedDelta * 10) / 10,
                novelty: ds.novelty,
                noveltyDelta: Math.round(noveltyDelta * 10) / 10,
                risk: ds.risk,
                riskDelta: Math.round(riskDelta),
                budgetUsed: ds.budgetUsed,
                builtFirst: ds.builtFirst,
                aiOracle: ds.aiOracle,
                sprayed: ds.sprayed,
                wrongBuyer: ds.wrongBuyer,
                optionalityAddicted: ds.optionalityAddicted,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMonths(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Number(v).toFixed(1);
            return (lang === `es`) ? n.replace(`.`, `,`) : n;
        }

        _fmtMoney(v) {
            // Canadian dollars, kept visually distinct from US$: "C$25k".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v));
            return (lang === `es`) ? `${n} k C$` : `C$${n}k`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`runwayDisplay`, `domainState.runway`, (v) => {
                const card = document.querySelector(`.commsim-card-runway`);
                if (card) {
                    card.classList.toggle(`commsim-runway-critical`, Number(v) < 6);
                    card.classList.toggle(`commsim-runway-healthy`, Number(v) >= 11);
                }
                return self._fmtMonths(Number(v));
            });
            uiManager.bind(`validatedDisplay`, `domainState.validated`, (v) => {
                const n = Number(v);
                return (Math.abs(n - Math.round(n)) < 0.05) ? String(Math.round(n)) : self._fmtMonths(n);
            });
            uiManager.bind(`noveltyDisplay`, `domainState.novelty`, (v) => self._fmtMonths(Number(v)));
            uiManager.bind(`riskDisplay`, `domainState.risk`, (v) => {
                const card = document.querySelector(`.commsim-card-risk`);
                if (card) {
                    card.classList.toggle(`commsim-risk-high`, Number(v) >= 65);
                    card.classList.toggle(`commsim-risk-low`, Number(v) <= 30);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.VALIDATION_BUDGET);
            });

            // Focus slider readout (R1).
            const fc = document.getElementById(`focusInput`);
            const fcReadout = document.getElementById(`focusReadout`);
            if (fc && fcReadout) {
                fcReadout.textContent = fc.value;
                fc.addEventListener(`input`, function() { fcReadout.textContent = fc.value; });
            }

            // Novelty target slider readout (R2).
            const nv = document.getElementById(`noveltyInput`);
            const nvReadout = document.getElementById(`noveltyReadout`);
            if (nv && nvReadout) {
                nvReadout.textContent = nv.value;
                nv.addEventListener(`input`, function() { nvReadout.textContent = nv.value; });
            }

            // Time-to-MVP slider readout (R4).
            const tm = document.getElementById(`ttmInput`);
            const tmReadout = document.getElementById(`ttmReadout`);
            if (tm && tmReadout) {
                tmReadout.textContent = tm.value;
                tm.addEventListener(`input`, function() { tmReadout.textContent = tm.value; });
            }

            // Validation-budget live total (must hit C$25k).
            const allocIds = [`interviewsInput`, `smokeInput`, `pilotInput`, `conciergeInput`, `fieldInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total % 1 === 0 ? String(total) : total.toFixed(1);
                const bar = document.querySelector(`.commsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.VALIDATION_BUDGET) > 0.001) ? `#ff5c74` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
                commChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: window.mySimulation.t(`legend_validated`),
                                data: [],
                                borderColor: `#7cf0d8`,
                                backgroundColor: `rgba(124,240,216,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#7cf0d8`,
