                            },
                            {
                                label: window.mySimulation.t(`legend_novelty`),
                                data: [],
                                borderColor: `#7c9cff`,
                                backgroundColor: `rgba(124,156,255,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7c9cff`,
