                                pointBackgroundColor: `#ffce6b`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#c8c7ea`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#9694c2` }, grid: { color: `rgba(255,255,255,0.06)` },
                                title: { display: true, text: `0–100 (scaled)`, color: `#9694c2` }
                            },
                            x: {
                                ticks: { color: `#9694c2` }, grid: { color: `rgba(255,255,255,0.04)` },
                                title: { display: true, text: window.mySimulation.t(`axis_round`), color: `#9694c2` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.validatedHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            // Validated is 0-20; scale ×5 to share the 0-100 axis. Novelty 1-5 ×4 ≈ 4-20 → ×... keep readable: ×4 then it sits low.
            return {
                commChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.validatedHistory.map((v) => Math.round(v * 5)) },
                        { data: ds.noveltyHistory.map((v) => Math.round(v * 4 * 5)) },
                        { data: ds.riskHistory },
                        { data: ds.runwayHistory.map((v) => Math.round(Math.max(0, v) * 5)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 composite formula, verbatim — single source of truth.
            const runway = ds.runway;
            const validated = ds.validated;
            const novelty = ds.novelty;
            const risk = Math.round(ds.risk);
            const runwayScore = Math.max(0, Math.min(100, (runway / this.START_RUNWAY) * 100));
            const validatedScore = (validated / this.TOTAL_ASSUMPTIONS) * 100;
            const noveltyScore = ((novelty - 1) / 4) * 100;
            return Math.round(validatedScore * 0.30 + noveltyScore * 0.18 + (100 - risk) * 0.32 + runwayScore * 0.20);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const runway = ds.runway;
            const validated = ds.validated;
            const novelty = ds.novelty;
            const risk = Math.round(ds.risk);

            // Composite: validated learning, novelty, low risk, and surviving runway.
            const composite = this._composite(ds);

            const solvent = runway > 0;
            const fundable = validated >= 10 && risk <= 35 && !ds.optionalityAddicted;
            const novel = novelty >= 4;
            const blewRunway = runway <= 6 || ds.builtFirst && runway <= 8;

            let performanceKey = `grade_withheld`;
            if (solvent && fundable && novel && composite >= 75) performanceKey = `grade_beachhead`;
            else if (solvent && fundable) performanceKey = `grade_unlocked`;
            else if (ds.optionalityAddicted) performanceKey = `grade_optionality`;
            else if (blewRunway) performanceKey = `grade_runway`;
            else if (ds.aiOracle && novelty <= 2.5) performanceKey = `grade_ailookalike`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const met = solvent && fundable && novel && composite >= 75;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (solvent && fundable && novel) insights.push(window.mySimulation.t(`insight_won`));
            else if (ds.optionalityAddicted) insights.push(window.mySimulation.t(`insight_optionality`));
            else if (blewRunway) insights.push(window.mySimulation.t(`insight_runway`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.builtFirst) insights.push(window.mySimulation.t(`insight_buildfirst`));
            if (ds.aiOracle || novelty <= 2.5) insights.push(window.mySimulation.t(`insight_lownovelty`));
            if (ds.sprayed) insights.push(window.mySimulation.t(`insight_spray`));
            if (ds.wrongBuyer) insights.push(window.mySimulation.t(`insight_wrongbuyer`));
            if (validated >= 12 && risk <= 30) insights.push(window.mySimulation.t(`insight_evidenced`));

            return {
                runway: runway,
                validated: validated,
                novelty: novelty,
                risk: risk,
                solvent: solvent,
                fundable: fundable,
                novel: novel,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                blewRunway: !!blewRunway,
                optionalityAddicted: !!ds.optionalityAddicted,
                aiOracle: !!ds.aiOracle,
                builtFirst: !!ds.builtFirst,
                sprayed: !!ds.sprayed,
                wrongBuyer: !!ds.wrongBuyer,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="commsim-cm-badge ` + (s.met ? `commsim-cm-met` : `commsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.blewRunway) badges.push(`<span class="commsim-cm-badge commsim-cm-fail">` + t(`cm_fail_runway`) + `</span>`);
            if (s.optionalityAddicted) badges.push(`<span class="commsim-cm-badge commsim-cm-fail">` + t(`cm_fail_optionality`) + `</span>`);
            if (s.aiOracle) badges.push(`<span class="commsim-cm-badge commsim-cm-fail">` + t(`cm_fail_ai`) + `</span>`);
            if (s.builtFirst) badges.push(`<span class="commsim-cm-badge commsim-cm-fail">` + t(`cm_fail_build`) + `</span>`);
            if (s.sprayed) badges.push(`<span class="commsim-cm-badge commsim-cm-fail">` + t(`cm_fail_spray`) + `</span>`);
            if (s.wrongBuyer) badges.push(`<span class="commsim-cm-badge commsim-cm-fail">` + t(`cm_fail_buyer`) + `</span>`);
            const kpi = (label, val) => `<div class="commsim-cm-metric"><div class="commsim-cm-metric-val">` + val + `</div><div class="commsim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_runway`), (s.runway != null ? Math.round(s.runway) : 0))
                + kpi(t(`cm_validated`), (s.validated != null ? s.validated : 0))
                + kpi(t(`cm_novelty`), (s.novelty != null ? s.novelty : 0))
                + kpi(t(`cm_risk`), (s.risk != null ? Math.round(s.risk) : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="commsim-cm">`
                + `<div class="commsim-cm-head"><div class="commsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="commsim-cm-scorewrap"><span class="commsim-cm-score">` + score + `</span><span class="commsim-cm-score-max">/100</span></div>`
                + `<div class="commsim-cm-grade">` + grade + `</div>`
                + `<div class="commsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="commsim-cm-metrics">` + kpis + `</div>`
                + `<div class="commsim-cm-insights"><div class="commsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.runway <= 6) return window.mySimulation.t(`hint_runway`);
            if (ds.optionalityAddicted) return window.mySimulation.t(`hint_optionality`);
            if (ds.aiOracle || (state.currentPeriod >= 2 && ds.novelty <= 2.5)) return window.mySimulation.t(`hint_novelty`);
            if (ds.wrongBuyer) return window.mySimulation.t(`hint_wrongbuyer`);
            if (state.currentPeriod >= 3 && ds.validated < 8) return window.mySimulation.t(`hint_validate`);
            if (ds.risk >= 65) return window.mySimulation.t(`hint_risk`);
            if (ds.validated >= 12 && ds.risk <= 30 && ds.runway >= 8) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.runway`, label: `Runway`, i18nKey: `col_runway`, formatter: (v) => self._fmtMonths(Number(v)) },
                { key: `results.validated`, label: `Validated`, i18nKey: `col_validated`, formatter: (v) => self._fmtMonths(Number(v)) },
                { key: `results.novelty`, label: `Novelty`, i18nKey: `col_novelty`, formatter: (v) => self._fmtMonths(Number(v)) },
                { key: `results.risk`, label: `Risk`, i18nKey: `col_risk`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

