                    warn_focus_range:       `Carry between 1 and 4 candidate markets.`,
                    warn_novelty_range:     `The novelty bar must be between 1 and 5.`,
                    warn_alloc_negative:    `Validation-budget allocations cannot be negative.`,
                    warn_alloc_total:       `The validation budget must total exactly C$25k — it is fixed. Re-balance the experiments.`,
                    warn_ttm_range:         `Time-to-MVP must be between 2 and 20 weeks.`,
